// 1) INGRESSO E VALIDAZIONE: controllo i campi obbligatori PRIMA di scrivere su Supabase
const b = $input.first().json.body || {};
const errori = [];
const richiesta_id = String(b.richiesta_id ?? '').trim();
const fornitore = String(b.fornitore ?? '').trim();
if (!richiesta_id) errori.push('Campo obbligatorio mancante: richiesta_id');
if (!fornitore) errori.push('Campo obbligatorio mancante: fornitore');
const somma = {};
if (!Array.isArray(b.righe) || b.righe.length === 0) {
  errori.push('Campo obbligatorio mancante: righe (serve almeno un articolo)');
} else {
  b.righe.forEach((r, i) => {
    const codice = String(r?.codice ?? '').trim().toUpperCase();
    const q = Number(r?.quantita);
    if (!codice) errori.push(`righe[${i}]: manca il codice`);
    if (!Number.isInteger(q) || q <= 0) errori.push(`righe[${i}]: quantita deve essere un numero intero maggiore di 0`);
    if (codice && Number.isInteger(q) && q > 0) somma[codice] = (somma[codice] || 0) + q; // stesso codice ripetuto => sommo
  });
}
return [{ json: {
  valido: errori.length === 0,
  errori,
  richiesta_id,
  fornitore,
  righe: Object.entries(somma).map(([codice, quantita]) => ({ codice, quantita }))
} }];

